import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'
import { useSearchParams } from 'react-router-dom'

import {
  Box,
  Button,
  Card,
  CircularProgress,
  Container,
  Stack,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import PageTitleWrapper from 'src/components/PageTitleWrapper'

import PartnerStoreForm from 'src/content/users/admin/PartnerStoreForm'

import { usePartnerBenefits } from 'src/hooks/usePartnerBenefits'

const BenefitStoreFormPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const {
    stores,
    createPartnerStore,
    updatePartnerStore,
    uploadPartnerStoreImage,
    deletePartnerStoreImage,
    isLoading,
    isFetching
  } = usePartnerBenefits({ mode: 'admin' })
  const benefitStoreIdParam = searchParams.get('benefitStoreId')
  const benefitStoreId = benefitStoreIdParam ? Number(benefitStoreIdParam) : null
  const isEditMode = benefitStoreId !== null
  const editingStore = benefitStoreId
    ? stores.find(store => store.id === benefitStoreId && !store.deletedAt)
    : undefined
  const isWaitingForEditingStore = isEditMode && !editingStore && (isLoading || isFetching)

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  const handleStoreManageButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-stores')
  }

  return (
    <>
      <Helmet>
        <title>제휴 가게 등록 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>{isEditMode ? '제휴 가게 수정' : '제휴 가게 등록'}</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              쿠폰에 연결할 가게명과 필요한 부가 정보를 입력합니다.
            </Typography>
          </Box>
          <Button variant="outlined" onClick={handleAdminButtonClick}>
            어드민 페이지
          </Button>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="lg">
        <Card sx={{ p: { xs: 2, md: 3 }, boxShadow: theme.header.boxShadow }}>
          {isWaitingForEditingStore ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : isEditMode && !editingStore ? (
            <Stack alignItems="center" spacing={2} sx={{ py: 4 }}>
              <Typography variant="h4">수정할 제휴 가게를 찾을 수 없습니다.</Typography>
              <Button variant="outlined" onClick={handleStoreManageButtonClick}>
                등록된 가게 리스트 보기
              </Button>
            </Stack>
          ) : (
            <PartnerStoreForm
              editingStore={editingStore}
              onCreatePartnerStore={createPartnerStore}
              onUpdatePartnerStore={updatePartnerStore}
              onUploadPartnerStoreImage={uploadPartnerStoreImage}
              onDeletePartnerStoreImage={deletePartnerStoreImage}
            />
          )}
        </Card>
      </Container>
    </>
  )
}

export default BenefitStoreFormPage
